def even_odd_count(num):
    """Given an integer, return a tuple (even_count, odd_count) representing
    the number of even and odd digits respectively.

    Examples:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    n = abs(num)
    # Handle zero explicitly: it has one digit which is even
    if n == 0:
        return (1, 0)

    even = 0
    odd = 0
    for ch in str(n):
        digit = int(ch)
        if digit % 2 == 0:
            even += 1
        else:
            odd += 1
    return (even, odd)
